use anyhow::{Context,Result};
use scratchpad_core::*; use scratchpad_storage::Repository; use std::sync::{Arc,Mutex}; use tokio::{io::{AsyncBufReadExt,AsyncWriteExt,BufReader},net::{UnixListener,UnixStream}};

#[tokio::main] async fn main()->Result<()> { let paths=Paths::discover(); std::fs::create_dir_all(&paths.runtime_dir)?; if paths.socket.exists(){std::fs::remove_file(&paths.socket)?;} let repo=Arc::new(Mutex::new(Repository::open(&paths.db())?)); let listener=UnixListener::bind(&paths.socket).with_context(||format!("bind {}",paths.socket.display()))?; eprintln!("scratchpad-daemon listening on {}",paths.socket.display()); loop { let (stream,_)=listener.accept().await?; let repo=repo.clone(); tokio::spawn(async move{if let Err(e)=handle(stream,repo).await{eprintln!("client error: {e:#}")}}); } }

async fn handle(stream:UnixStream,repo:Arc<Mutex<Repository>>)->Result<()> { let (r,mut w)=stream.into_split(); let mut lines=BufReader::new(r).lines(); while let Some(line)=lines.next_line().await? { let env:RequestEnvelope=serde_json::from_str(&line)?; let response=dispatch(&repo,env.request); let out=ResponseEnvelope{id:env.id,response}; w.write_all(serde_json::to_string(&out)?.as_bytes()).await?; w.write_all(b"\n").await?; } Ok(()) }
fn dispatch(repo:&Arc<Mutex<Repository>>, req:Request)->Response { let r=repo.lock().unwrap(); let x:anyhow::Result<Response>=(||Ok(match req { Request::Ping=>Response::Pong, Request::ListPages=>Response::Pages(r.list_pages()?), Request::CreatePage{name}=>{let p=r.create_page(&name)?;Response::Created{id:p.id}}, Request::GetPage{page_id}=>Response::Page(r.page_snapshot(page_id)?), Request::AddObject{object,page_id,placement}=>{let id=object.id;r.insert_object(&object,page_id,placement.as_ref())?;Response::Created{id}}, Request::ListObjects{limit}=>Response::Objects(r.list_objects(limit)?), Request::GetObject{object_id}=>Response::Object(r.get_object(object_id)?.context("object not found")?), Request::RemoveObject{object_id}=>{r.remove_object(object_id)?;Response::Removed} }))(); x.unwrap_or_else(|e|Response::Error{message:format!("{e:#}")}) }
